/* Add racial mount items */
DELETE FROM `item_template` WHERE `entry` IN (@WorgenMount1Item, @WorgenMount2);

/* Add Cataclysm starting equipment for worgen */
DELETE FROM `item_template` WHERE  `entry` IN (
    @GilneanTrappersBootsItem,    @GilneanTrappersGlovesItem,   @GilneanTrappersShirtItem,   @GilneanTrappersTunicItem,
    @GilneanFootpadsBootsItem,    @GilneanFootpadsGlovesItem,   @GilneanFootpadsPantsItem,   @GilneanFootpadsTunicItem,
    @GilneanRecruitsBeltItem,     @GilneanRecruitsBootsItem,    @GilneanRecruitsPantsItem,   @GilneanRecruitsTunicItem,
    @GilneanNovicesBootsItem,     @GilneanNovicesGlovesItem,    @GilneanNovicesPantsItem,    @GilneanNovicesTunicItem,
    @GilneanApprenticesBootsItem, @GilneanApprenticesPantsItem, @GilneanApprenticesRobeItem,
    @GilneanNeophytesBootsItem,   @GilneanNeophytesPantsItem,   @GilneanNeophytesRobeItem,
    @GilneanAcolytesBootsItem,    @GilneanAcolytesPantsItem,    @GilneanAcolytesRobeItem,
    @GilneanAdventurersShirtItem
);
